{

"kind": "propose",
"summary": "Adjust liveness probe timeout and initial delay to match observed startup duration",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe kills app during startup due to insufficient timeout and delay",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "Logs confirm app starts but probe fails before readiness",
    "supporting": ["crashed_on_its_own", "ev-container_logs_tail"],
    "contradicting": ["killed_during_startup"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 30,
      "timeoutSeconds": 30
    }
  },
  "expected_effect": "Allow 30s startup window before liveness probe kills container",
  "rationale": "Logs show app took 30s to start (10:26:10-10:26:40) but liveness probe failed at 10:26:40. Current timeout (1s) is insufficient. Increasing both initialDelaySeconds and timeoutSeconds to 30s aligns with observed startup duration from killed_during_startup evidence.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
